import * as React from "react"

import { cn } from "@/lib/utils"

import "@/components/ui/typography.css"

type TypesetElement = "article" | "div" | "section"

type TypesetProps = React.HTMLAttributes<HTMLElement> & {
  as?: TypesetElement
  density?: "compact" | "default" | "comfortable"
}

function Typeset({
  as: Component = "div",
  className,
  density = "default",
  ...props
}: TypesetProps) {
  return (
    <Component
      data-slot="typeset"
      data-density={density}
      className={cn(
        "typeset",
        density !== "default" && `typeset-${density}`,
        className
      )}
      {...props}
    />
  )
}

function TypesetScroll({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="typeset-scroll"
      className={cn("typeset-scroll", className)}
      {...props}
    />
  )
}

export { Typeset, TypesetScroll, type TypesetProps }

/*
 * Based on shadcn/typeset.
 * https://ui.shadcn.com/docs/typeset
 */

@layer components {
  .typeset {
    --typeset-font-body: var(--font-sans);
    --typeset-font-heading: var(--font-heading);
    --typeset-font-mono: var(--font-mono);
    --typeset-size: var(--typeset-config-size, var(--text-base));
    --typeset-leading: var(--typeset-config-leading, 1.75);
    --typeset-flow: var(--typeset-config-flow, 1.25em);
    --typeset-measure: var(--typeset-config-measure, 65ch);

    margin-trim: block-start;
    max-inline-size: var(--typeset-measure);
    overflow-wrap: break-word;
    color: var(--color-foreground, currentColor);
    font-family: var(--typeset-font-body);
    font-size: var(--typeset-size);
    line-height: var(--typeset-leading);
    --typeset-muted: var(
      --color-muted-foreground,
      color-mix(in oklab, currentColor 60%, transparent)
    );
    --typeset-rule: var(
      --color-border,
      color-mix(in oklab, currentColor 20%, transparent)
    );
  }

  .typeset-compact {
    --typeset-size: var(--text-sm);
    --typeset-leading: 1.6;
    --typeset-flow: 1em;
    --typeset-measure: 58ch;
  }

  .typeset-comfortable {
    --typeset-size: var(--text-lg);
    --typeset-leading: 1.9;
    --typeset-flow: 1.5em;
    --typeset-measure: 68ch;
  }

  .typeset
    *:not(
      :where(
        .not-typeset,
        [data-not-typeset],
        .not-typeset *,
        [data-not-typeset] *
      )
    ) {
    &:where(p) {
      margin-block: var(--typeset-flow) 0;
    }

    &:where(h1, h2, h3, h4, h5, h6) {
      margin-block-end: 0;
      color: var(--color-foreground, currentColor);
      font-family: var(--typeset-font-heading);
      font-weight: var(--font-weight-semibold);
    }

    &:where(h1) {
      margin-block-start: var(--typeset-flow);
      font-size: 1.75em;
      line-height: 1.3;
    }

    &:where(h2) {
      margin-block-start: calc(var(--typeset-flow) * 1.4);
      font-size: 1.25em;
      line-height: 1.4;
    }

    &:where(h3) {
      margin-block-start: var(--typeset-flow);
      font-size: 1.125em;
      line-height: 1.45;
    }

    &:where(h4) {
      margin-block-start: var(--typeset-flow);
      font-size: 1em;
      line-height: 1.5;
    }

    &:where(h5) {
      margin-block-start: calc(var(--typeset-flow) / 0.875);
      color: var(--typeset-muted);
      font-size: 0.875em;
      font-weight: var(--font-weight-medium);
      line-height: 1.5;
    }

    &:where(h6) {
      margin-block-start: calc(var(--typeset-flow) / 0.8125);
      color: var(--typeset-muted);
      font-size: 0.8125em;
      font-weight: var(--font-weight-medium);
      letter-spacing: 0.08em;
      line-height: 1.5;
      text-transform: uppercase;
    }

    &:where([id]) {
      scroll-margin-block-start: var(--typeset-flow);
    }

    &:where(h1 + *, h2 + *, h3 + *, h4 + *, h5 + *, h6 + *) {
      margin-block-start: 1em;
    }

    &:where(:is(h1, h2, h3, h4) :is(code)) {
      font-size: 0.9em;
    }

    &:where(a) {
      color: inherit;
      font-weight: 500;
      text-decoration-color: color-mix(in oklab, currentColor 30%, transparent);
      text-decoration-line: underline;
    }

    &:where(a:hover) {
      text-decoration-color: currentColor;
    }

    &:where(a:focus-visible) {
      border-radius: 0.125em;
      outline: var(--border-width-strong) solid var(--color-ring, currentColor);
      outline-offset: 2px;
    }

    &:where(strong, b) {
      font-weight: var(--font-weight-semibold);
    }

    &:where(mark) {
      border-radius: 0.2em;
      background-color: color-mix(
        in oklab,
        var(--color-primary, currentColor) 24%,
        transparent
      );
      padding: 0.05em 0.15em;
      color: inherit;
    }

    &:where(abbr[title]) {
      cursor: help;
      text-decoration-line: underline;
      text-decoration-style: dotted;
      text-underline-offset: 0.2em;
    }

    &:where(del, s) {
      color: var(--typeset-muted);
      text-decoration-line: line-through;
    }

    &:where(sup, sub) {
      position: relative;
      font-size: 0.75em;
      line-height: 0;
      vertical-align: baseline;
    }

    &:where(sup) {
      top: -0.5em;
    }

    &:where(sub) {
      bottom: -0.25em;
    }

    &:where(ul) {
      list-style-type: disc;
    }

    &:where(ol) {
      list-style-type: decimal;
    }

    &:where(ul ul) {
      list-style-type: circle;
    }

    &:where(ul ul ul) {
      list-style-type: square;
    }

    &:where(ul, ol) {
      margin-block: var(--typeset-flow) 0;
      padding-inline-start: 1.5em;
    }

    &:where(li) {
      margin-block-start: 0.5em;
      padding-inline-start: 0.4em;
    }

    &:where(li > p, li > ul, li > ol) {
      margin-block-start: 0.5em;
    }

    &:where(ul > li, ol > li)::marker {
      color: var(--typeset-muted);
    }

    &:where(ul.contains-task-list) {
      padding-inline-start: 0.25em;
      list-style-type: none;
    }

    &:where(li.task-list-item > input[type="checkbox"]) {
      margin-inline-end: 0.5em;
      accent-color: var(--color-primary, currentColor);
      vertical-align: -0.1em;
    }

    &:where(details) {
      margin-block: var(--typeset-flow) 0;
    }

    &:where(summary) {
      cursor: pointer;
      font-weight: 500;
    }

    &:where(summary)::marker {
      color: var(--typeset-muted);
    }

    &:where(kbd) {
      border: 1px solid var(--typeset-rule);
      border-block-end-width: 2px;
      border-radius: min(calc(var(--radius, 0.5em) * 0.6), 0.35em);
      padding: 0.0625em 0.35em;
      font-family: inherit;
      font-size: 0.85em;
      font-weight: 500;
    }

    &:where(dl) {
      margin-block: var(--typeset-flow) 0;
    }

    &:where(dt) {
      margin-block-start: 1em;
      font-weight: 500;
    }

    &:where(dd) {
      margin-block-start: 0.25em;
      margin-inline-start: 0;
      padding-inline-start: 1em;
      color: var(--typeset-muted);
    }

    &:where(:not(pre) > code) {
      border-radius: min(calc(var(--radius, 0.5em) * 0.6), 0.35em);
      background-color: var(
        --color-muted,
        color-mix(in oklab, currentColor 8%, transparent)
      );
      padding: 0.125em 0.3em;
      font-family: var(--typeset-font-mono);
      font-size: 0.85em;
    }

    &:where(pre) {
      overflow-x: auto;
      margin-block: calc(var(--typeset-flow) / 0.875) 0;
      border-radius: var(--radius, 0.5em);
      background-color: var(
        --color-muted,
        color-mix(in oklab, currentColor 8%, transparent)
      );
      padding: 0.75em 1em;
      direction: ltr;
      font-family: var(--typeset-font-mono);
      font-size: 0.875em;
      line-height: 1.5;
      tab-size: 2;
    }

    &:where(pre code) {
      border-radius: 0;
      background-color: transparent;
      padding: 0;
      font-family: inherit;
      font-size: inherit;
    }

    &:where(blockquote) {
      margin-block: var(--typeset-flow) 0;
      margin-inline: 0;
      border-inline-start: 2px solid var(--typeset-rule);
      padding-inline-start: 1em;
    }

    &:where(hr) {
      margin-block: calc(var(--typeset-flow) * 2.4) 0;
      border: 0;
      border-block-start: 1px solid var(--typeset-rule);
    }

    &:where(.footnotes, [data-footnotes]) {
      margin-block-start: calc(var(--typeset-flow) * 2);
      border-block-start: 1px solid var(--typeset-rule);
      padding-block-start: var(--typeset-flow);
      color: var(--typeset-muted);
      font-size: 0.875em;
    }

    &:where(img, video) {
      max-width: 100%;
      height: auto;
      margin-block: var(--typeset-flow) 0;
      border-radius: var(--radius, 0.5em);
    }

    &:where(figure) {
      margin-block: var(--typeset-flow) 0;
      margin-inline: 0;
    }

    &:where(figcaption, caption) {
      margin-block-start: calc(0.75em / 0.875);
      color: var(--typeset-muted);
      font-size: 0.875em;
      text-align: center;
    }

    &:where(caption) {
      caption-side: bottom;
    }

    &:where(table) {
      max-width: 100%;
      margin-block: var(--typeset-flow) 0;
      border-spacing: 0;
      border-collapse: separate;
      border-block-end: 1px solid var(--typeset-rule);
      font-size: 1em;
      font-variant-numeric: tabular-nums;
      line-height: 1.5;
    }

    &:where(.typeset-scroll) {
      overflow-x: auto;
      margin-block-start: var(--typeset-flow);
    }

    &:where(.typeset-scroll > *) {
      margin-block-start: 0;
    }

    &:where(.typeset-scroll table) {
      width: max-content;
      max-width: none;
    }

    &:where(thead th) {
      padding: 0.65em 1em;
      font-weight: 500;
      text-align: start;
      white-space: nowrap;
    }

    &:where(:is(tbody, tfoot) :is(td, th)) {
      border-block-start: 1px solid var(--typeset-rule);
      padding: 0.75em 1em;
      text-align: start;
      vertical-align: top;
    }

    &:where(th:first-child, td:first-child) {
      padding-inline-start: 0;
    }

    @media print {
      &:where(pre, table, blockquote, figure) {
        break-inside: avoid;
      }

      &:where(h1, h2, h3, h4) {
        break-after: avoid;
      }
    }

    @media (forced-colors: active) {
      &:where(:not(pre) > code) {
        border: 1px solid;
      }
    }
  }

  .typeset
    > :where(:first-child):not(
      :where(
        .not-typeset,
        [data-not-typeset],
        .not-typeset *,
        [data-not-typeset] *
      )
    ),
  .typeset
    :where(
      li > :first-child,
      blockquote > :first-child,
      td > :first-child,
      th > :first-child,
      dd > :first-child,
      figure > :first-child
    ):not(
      :where(
        .not-typeset,
        [data-not-typeset],
        .not-typeset *,
        [data-not-typeset] *
      )
    ) {
    margin-block-start: 0;
  }
}
